<script setup>
import { onMounted, reactive, ref } from 'vue'
import FloatingWindow from '../components/common/FloatingWindow.vue'
import NeonPanel from '../components/common/NeonPanel.vue'
import { useAppStore } from '../stores/app'

const store = useAppStore()
const hierarchy = ref({ projects: [], organizations: [], environments: [] })
const projectWindow = ref(false)
const environmentWindow = ref(false)
const projectDraft = reactive({ id: '', organizationId: 'org-default', name: '', description: '' })
const environmentDraft = reactive({ id: '', projectId: '', name: '', environmentType: 'custom', isProtected: false, requireApproval: false })
async function refresh() { hierarchy.value = await store.listProjects() }
function openProject(project = null) { Object.assign(projectDraft, project ? { id: project.id, organizationId: project.organization_id, name: project.name, description: project.description || '' } : { id: '', organizationId: 'org-default', name: '', description: '' }); projectWindow.value = true }
function openEnvironment(project, environment = null) { Object.assign(environmentDraft, environment ? { id: environment.id, projectId: project.id, name: environment.name, environmentType: environment.environment_type, isProtected: environment.isProtected, requireApproval: environment.requireApproval } : { id: '', projectId: project.id, name: '', environmentType: 'custom', isProtected: false, requireApproval: false }); environmentWindow.value = true }
async function saveProject() { await store.saveProject(projectDraft); projectWindow.value = false; await refresh() }
async function saveEnvironment() { await store.saveEnvironment(environmentDraft); environmentWindow.value = false; await refresh() }
function selectScope(project, environment) { store.setActiveScope({ projectId: project.id, environmentId: environment.id }) }
onMounted(refresh)
</script>

<template><div class="projects-workspace"><div class="toolbar-row"><div><p class="section-eyebrow">Operational Boundaries</p><h2 class="page-title">Projects And Environments</h2></div><v-btn class="glass-button" prepend-icon="mdi-folder-plus-outline" @click="openProject()">Create Project</v-btn></div><v-alert type="info" variant="tonal" density="compact">Active scope: <strong>{{ hierarchy.projects.flatMap((project) => project.environments.map((environment) => ({ project, environment }))).find((item) => item.project.id === store.activeScope.projectId && item.environment.id === store.activeScope.environmentId)?.project.name || 'Default Project' }}</strong> / {{ hierarchy.environments.find((environment) => environment.id === store.activeScope.environmentId)?.name || 'Production' }}. New scripts, nodes, credentials, groups, and schedules inherit this scope.</v-alert><NeonPanel subtitle="Partitioned Automation" title="Project Portfolio"><div class="project-grid"><article v-for="project in hierarchy.projects" :key="project.id" class="project-card"><div class="project-head"><div><strong>{{ project.name }}</strong><span>{{ project.organization_name }}</span></div><v-btn size="x-small" icon="mdi-pencil-outline" variant="text" @click="openProject(project)"/></div><p>{{ project.description || 'No description provided.' }}</p><div class="environment-row" v-for="environment in project.environments" :key="environment.id"><v-btn size="x-small" :color="store.activeScope.environmentId === environment.id ? 'secondary' : undefined" variant="tonal" @click="selectScope(project, environment)">{{ environment.name }}</v-btn><span>{{ environment.environment_type }}{{ environment.isProtected ? ' · protected' : '' }}{{ environment.requireApproval ? ' · approval required' : '' }}</span><v-btn size="x-small" icon="mdi-cog-outline" variant="text" @click="openEnvironment(project, environment)"/></div><v-btn size="small" variant="text" prepend-icon="mdi-plus" @click="openEnvironment(project)">Add Environment</v-btn></article></div></NeonPanel><FloatingWindow v-model="projectWindow" :title="projectDraft.id ? 'Edit Project' : 'Create Project'" :width="520" :start-x="320" :start-y="115"><form class="project-form" @submit.prevent="saveProject"><v-select v-model="projectDraft.organizationId" :items="hierarchy.organizations" item-title="name" item-value="id" label="Organization"/><v-text-field v-model="projectDraft.name" label="Project name"/><v-textarea v-model="projectDraft.description" label="Purpose and ownership" rows="3"/><div class="window-actions"><v-btn variant="text" @click="projectWindow = false">Cancel</v-btn><v-btn class="glass-button" type="submit">Save Project</v-btn></div></form></FloatingWindow><FloatingWindow v-model="environmentWindow" :title="environmentDraft.id ? 'Edit Environment' : 'Add Environment'" :width="520" :start-x="390" :start-y="145"><form class="project-form" @submit.prevent="saveEnvironment"><v-text-field v-model="environmentDraft.name" label="Environment name"/><v-select v-model="environmentDraft.environmentType" :items="['dev', 'test', 'prod', 'custom']" label="Environment type"/><v-switch v-model="environmentDraft.isProtected" density="compact" color="warning" label="Protected environment"/><v-switch v-model="environmentDraft.requireApproval" density="compact" color="secondary" label="Require approval for change or execution"/><div class="window-actions"><v-btn variant="text" @click="environmentWindow = false">Cancel</v-btn><v-btn class="glass-button" type="submit">Save Environment</v-btn></div></form></FloatingWindow></div></template>

<style scoped>.projects-workspace,.project-grid,.project-form { display:grid; gap:14px; }.project-grid { grid-template-columns:repeat(auto-fit,minmax(300px,1fr)); padding:14px; }.project-card { display:grid; gap:10px; padding:14px; border:1px solid var(--line); background:linear-gradient(135deg,rgba(40,211,255,.06),rgba(190,77,255,.04)); }.project-head,.environment-row,.window-actions { display:flex; align-items:center; gap:8px; }.project-head { justify-content:space-between; }.project-head div { display:grid; gap:2px; }.project-head span,.project-card p,.environment-row span { color:var(--muted); font-size:.76rem; }.environment-row { padding:8px 0; border-top:1px solid var(--line); }.environment-row span { flex:1; }</style>
